import { PageHeaderModule } from 'src/app/view/components/app/page-header/page-header.module';
import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';

import { InstagramBotRoutingModule } from './instagram-bot-routing.module';
import { InstagramBotComponent } from './instagram-bot.component';
import { HttpClientModule, HTTP_INTERCEPTORS } from '@angular/common/http';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { IonicModule } from '@ionic/angular';
import { AccountInterceptor } from 'src/app/core/utility/account.interceptor';
import { SliderService } from 'src/app/data/service/site/Slider.service';
import { LoadingModule } from 'src/app/view/components/common/loading/loading.module';
import { FooterModule } from 'src/app/view/components/app/footer/footer.module';



@NgModule({
  declarations: [InstagramBotComponent],
  imports: [
    PageHeaderModule,
    CommonModule,
    InstagramBotRoutingModule,
    IonicModule,
    HttpClientModule,
    FormsModule,
    ReactiveFormsModule,
    
    FooterModule,
    LoadingModule
  ],
  providers: [
    SliderService,
    {
      provide: HTTP_INTERCEPTORS,
      useClass: AccountInterceptor,
      multi: true
    }
  ]
})
export class InstagramBotModule { }
