import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { InstagramBotComponent } from './instagram-bot.component';

const routes: Routes = [{ path: '', component: InstagramBotComponent }];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class InstagramBotRoutingModule { }
