import { Component, OnInit } from '@angular/core';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { GResponse } from '../../../../core/common/GResponse';
import { InstagramFollowersDirectMsgModel, InstagramUserDirectMsgModel } from '../../../../data/model/site/SliderModel';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { SliderService } from 'src/app/data/service/site/Slider.service';
import { GAccount } from '../../../../core/common/GAccount';
import { Router } from '@angular/router';
import { Urls } from '../../../../core/common/Urls';

@Component({
  selector: 'app-instagram-bot',
  templateUrl: './instagram-bot.component.html',
  styleUrls: ['./instagram-bot.component.scss']
})
export class InstagramBotComponent implements OnInit {

  directForm: FormGroup;
  followersForm: FormGroup;
  segmentSelected = 'Direct';
  sendProfile = false;

  constructor(
    private sliderService: SliderService,
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController,
    public alertController: AlertController,
    private router: Router
  ) {

  }

  ngOnInit(): void {

    if (!GAccount.IsLoggedIn()) {
      this.router.navigateByUrl(Urls.AccessDeniedUrl);
    }
    if (GAccount.UserEmail == null || !(GAccount.UserEmail === 'nikerfan041@gmail.com' || GAccount.UserEmail === 'nima.dr13@gmail.com')) {
      this.router.navigateByUrl(Urls.AccessDeniedUrl);
    }

    this.directForm = this.fb.group({
      userName: ['avalamooz.ir', [Validators.required, Validators.minLength(3), Validators.maxLength(10000)]],
      password: ['Nima@1375', [Validators.required, Validators.minLength(3), Validators.maxLength(10000)]],
      targetUserName: ['', [Validators.required, Validators.minLength(3), Validators.maxLength(10000)]],
      profileUserName: ['avalamooz.ir', [Validators.required, Validators.minLength(3), Validators.maxLength(10000)]],
      msg: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(10000000)]],
      link: ['', []],
      linkMsg: ['', []]
    });

    this.followersForm = this.fb.group({
      userName: ['avalamooz.ir', [Validators.required, Validators.minLength(3), Validators.maxLength(10000)]],
      password: ['Nima@1375', [Validators.required, Validators.minLength(3), Validators.maxLength(10000)]],
      profileUserName: ['avalamooz.ir', [Validators.required, Validators.minLength(3), Validators.maxLength(10000)]],
      msg: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(10000000)]],
      link: ['', []],
      linkMsg: ['', []]
    });
  }

  async presentAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به ارسال هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'ارسال',
          handler: () => {
            this.onSendToDirect();
          }
        }
      ]
    });

    await alert.present();
  }

  onSendToDirect() {

    return;

    if (!this.directForm.valid) {

      return;
    }

    if (this.directForm.value.link === '' && this.directForm.value.linkMsg !== '') {

      SharedIonic.toast(this.toastController, 'لینک خالی است! اما متن لینک وجود دارد!');
      return;
    }

    SharedIonic.loading(this.loadingController);

    this.sliderService.InstagramBotUserDirectMsg(
      new InstagramUserDirectMsgModel(
        this.directForm.value.userName,
        this.directForm.value.password,
        this.directForm.value.targetUserName,
        this.directForm.value.msg,
        this.directForm.value.link,
        this.directForm.value.linkMsg,
        this.directForm.value.profileUserName,
        this.sendProfile
      )
    ).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          this.directForm.setValue({
            userName: this.directForm.value.userName,
            password: this.directForm.value.password,
            targetUserName: '',
            msg: '',
            link: '',
            profileUserName: '',
            linkMsg: ''
          });
          this.sendProfile = false;
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  async presentAlertConfirm2() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به ارسال هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'ارسال',
          handler: () => {
            this.onSendToFollowers();
          }
        }
      ]
    });

    await alert.present();
  }

  onSendToFollowers() {

    return;

    if (!this.followersForm.valid) {

      return;
    }

    if (this.followersForm.value.link === '' && this.followersForm.value.linkMsg !== '') {

      SharedIonic.toast(this.toastController, 'لینک خالی است! اما متن لینک وجود دارد!');
      return;
    }

    SharedIonic.loading(this.loadingController);

    this.sliderService.InstagramBotFollowersDirectMsg(
      new InstagramFollowersDirectMsgModel(
        this.followersForm.value.userName,
        this.followersForm.value.password,
        this.followersForm.value.msg,
        this.followersForm.value.link,
        this.followersForm.value.linkMsg,
        this.followersForm.value.profileUserName,
        this.sendProfile
      )
    ).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          this.followersForm.setValue({
            userName: this.followersForm.value.userName,
            password: this.followersForm.value.password,
            msg: '',
            link: '',
            profileUserName: '',
            linkMsg: ''
          });
          this.sendProfile = false;
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  async presentAlertConfirm3() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به حذف هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'حذف',
          handler: () => {
            this.onRemoveSession();
          }
        }
      ]
    });

    await alert.present();
  }

  onRemoveSession() {

    return;

    SharedIonic.loading(this.loadingController);

    this.sliderService.RemoveInstagramSession().subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }
}
